<script setup lang="ts">
import {reactive,ref,onMounted} from 'vue'
import {api,user,refreshAuth,siteName,message,notify} from '../api'
const error=ref(''),ready=ref(false),saving=ref(false),accounts=ref<any[]>([]),qqs=ref<any[]>([]),catalog=ref<Record<string,string>>({}),tab=ref('站点与注册'),importText=ref(''),editing=ref<any>(null)
const form=reactive({siteName:'',siteDescription:'',registrationEnabled:true,registrationMode:'test'})
async function load(){error.value='';try{const [s,a,q]=await Promise.all([api.get('/admin/settings'),api.get('/admin/accounts'),api.get('/admin/registration/qq-allowlist')]);Object.assign(form,s.data);catalog.value=s.data.permissionCatalog;accounts.value=a.data;qqs.value=q.data;ready.value=true}catch(e){error.value=message(e)}}
async function save(){saving.value=true;error.value='';try{await api.put('/admin/settings',form);siteName.value=form.siteName;notify('后台配置已保存')}catch(e){error.value=message(e)}finally{saving.value=false}}
async function edit(id:number){try{editing.value=(await api.get(`/admin/accounts/${id}/permissions`)).data}catch(e){error.value=message(e)}}
async function savePermissions(){if(!editing.value)return;saving.value=true;try{const id=editing.value.id;await api.put(`/admin/accounts/${id}/permissions`,editing.value);editing.value=null;notify('账号权限已更新');await refreshAuth();if(user.value?.role==='ADMIN')await load()}catch(e){error.value=message(e)}finally{saving.value=false}}
async function importQqs(){saving.value=true;error.value='';try{const qqNumbers=importText.value.split(/[\s,，;；]+/).filter(Boolean);const r=await api.post('/admin/registration/qq-allowlist',{qqNumbers});importText.value='';notify(`已导入 ${r.data.count} 个 QQ 号`);await load()}catch(e){error.value=message(e)}finally{saving.value=false}}
async function disable(qq:string){try{await api.delete(`/admin/registration/qq-allowlist/${qq}`);await load()}catch(e){error.value=message(e)}}
onMounted(load)
</script>
<template><div class="container page-space admin-settings"><div class="section-heading"><div><p class="eyebrow">管理员 / 配置</p><h1 class="page-title">后台配置</h1></div><RouterLink to="/admin" class="text-button">返回社务台 →</RouterLink></div><div class="genre-tabs desk-tabs"><button v-for="t in ['站点与注册','账号权限','QQ 号库']" :key="t" :class="{selected:tab===t}" @click="tab=t;error='';editing=null">{{t}}</button></div><p v-if="error" class="error-message" role="alert">{{error}}</p><p v-if="!ready&&!error" class="quiet-note">加载中…</p><template v-if="ready"><form v-if="tab==='站点与注册'" class="panel profile-form" @submit.prevent="save"><label>站点名称<input v-model="form.siteName" maxlength="80" required/></label><label>站点介绍<textarea v-model="form.siteDescription" maxlength="300" rows="3"></textarea></label><label class="checkbox-label"><input v-model="form.registrationEnabled" type="checkbox"/>开放注册</label><label>QQ 与验证码校验模式<select v-model="form.registrationMode"><option value="test">测试模式（12345 / 0000）</option><option value="live">正式模式（QQ 号库与真实验证码）</option></select></label><p class="quiet-note">正式模式已预留邮件与机器人发送接口。未配置发送服务时，会提示不可用。</p><button class="button" :disabled="saving">保存配置</button></form><template v-else-if="tab==='账号权限'"><p class="quiet-note">权限对后续请求生效。管理员拥有全部权限，系统至少保留一位管理员。</p><div class="table-wrap"><table><thead><tr><th>账号</th><th>笔名</th><th>角色</th><th></th></tr></thead><tbody><tr v-for="m in accounts" :key="m.id"><td>{{m.username}}</td><td>{{m.penName}}</td><td>{{m.role==='ADMIN'?'管理员':'社员'}}</td><td><button @click="edit(m.id)">配置权限</button></td></tr></tbody></table></div><form v-if="editing" class="panel permission-editor" @submit.prevent="savePermissions"><h3>{{editing.username}}</h3><label>账号角色<select v-model="editing.role"><option value="MEMBER">社员</option><option value="ADMIN">管理员</option></select></label><label v-for="(label,code) in catalog" :key="code" class="checkbox-label"><input type="checkbox" v-model="editing.permissions[code]" :disabled="editing.role==='ADMIN'"/>{{label}}</label><div class="permission-actions"><button class="button" :disabled="saving">保存权限</button><button type="button" class="text-button" @click="editing=null">取消</button></div></form></template><template v-else><form class="panel profile-form" @submit.prevent="importQqs"><label>导入可用 QQ 号<textarea v-model="importText" rows="5" placeholder="每行一个，或用逗号分隔。每次最多 1000 个。" required></textarea></label><button class="button" :disabled="saving">导入 QQ 号</button><p class="quiet-note">QQ 号库在正式模式生效。测试模式仅接受 12345。</p></form><div class="table-wrap"><table><thead><tr><th>QQ 号</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="q in qqs" :key="q.qqNumber"><td>{{q.qqNumber}}</td><td>{{q.active?'可注册':'已停用'}}</td><td><button v-if="q.active" @click="disable(q.qqNumber)">停用</button></td></tr></tbody></table></div></template></template></div></template>
